var t=`1300-bobo-de-camarao`;var n=`world-1300`;var o=`BR`;var a=`south-america`;var s=4;var r=64;var l={en:`Bobó de Camarão`,ua:`Бобо де камарау`};var m={en:`Bobó de Camarão is a dish from Brazil featuring cassava root, coconut milk, yellow onion, tomato. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Бобо де камарау, страва кухні країни Бразилія з такими основними складниками: маніок, кокосове молоко, жовта цибуля, помідор. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Cook the listed ingredients in simmering water for about 28 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 28 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:28,i:[[`cassava-root`,740,`g`],[`water`,1100,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`coconut-milk`,420,`ml`],[`fish-stock`,200,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,180,`g`],[`tomato`,310,`g`],[`garlic`,5,`clove`],[`palm-oil`,45,`ml`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 14 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 14 хвилин до готовності й м’якості.`,t:[`poaching`],m:14,i:[[`shrimp`,650,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,28,`g`],[`lime`,1,`pcs`]]}];var g={slug:t,id:n,country:`BR`,region:a,servings:4,minutes:64,title:l,text:m,steps:d};export{o as country,g as default,n as id,r as minutes,a as region,s as servings,t as slug,d as steps,m as text,l as title};